import{_ as i}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o as a,X as e}from"./chunks/vendor-vueuse.XPft87tp.js";const g=JSON.parse('{"title":"MySQL 锁","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/mysql-lock.md","filePath":"mysql/mysql-lock.md","lastUpdated":1786990830000}'),l={name:"mysql/mysql-lock.md"};function n(r,s,d,o,p,h){return a(),t("div",null,s[0]||(s[0]=[e(`<h1 id="mysql-锁" tabindex="-1">MySQL 锁 <a class="header-anchor" href="#mysql-锁" aria-label="Permalink to &quot;MySQL 锁&quot;">​</a></h1><h3 id="锁加在索引记录上" tabindex="-1">锁加在索引记录上 <a class="header-anchor" href="#锁加在索引记录上" aria-label="Permalink to &quot;锁加在索引记录上&quot;">​</a></h3><p>并发事务访问同一资源时，锁用来排队，避免写写互相覆盖。InnoDB 的行锁挂在<strong>索引记录</strong>上，不是挂在物理行号上。<code>WHERE</code> 没有走索引，可能锁住大量记录，看起来就像锁表。</p><p>快照读（普通 <code>SELECT</code>）几乎不加行锁；当前读才加记录锁、间隙锁或 Next-Key。不要背「RR = 共享锁拿到事务结束」——那不是 InnoDB 默认一致性读的行为。</p><p>隔离级别决定锁的范围和持有时间：RR 的间隙锁更强，用来堵幻读；RC 对间隙更宽松，并发插入更好，幻读风险也更高。</p><h3 id="粒度、模式和意向锁" tabindex="-1">粒度、模式和意向锁 <a class="header-anchor" href="#粒度、模式和意向锁" aria-label="Permalink to &quot;粒度、模式和意向锁&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>表锁</th><th>行锁</th><th>页锁（少见）</th></tr></thead><tbody><tr><td>开销</td><td>小</td><td>大</td><td>中</td></tr><tr><td>加锁速度</td><td>快</td><td>慢</td><td>中</td></tr><tr><td>死锁</td><td>基本不会</td><td>会</td><td>可能</td></tr><tr><td>并发</td><td>低</td><td>高</td><td>中</td></tr></tbody></table><p>InnoDB 默认行锁。DDL、显式 <code>LOCK TABLES</code> 仍会用表锁。MyISAM 基本是表锁。</p><p>按模式：</p><ul><li><strong>共享锁 S</strong>：读。兼容其他 S，不兼容 X</li><li><strong>排他锁 X</strong>：写。和其他 S / X 都不兼容</li></ul><p>给整张表加 X 锁时，如果要扫每一行有没有行锁，代价过高。InnoDB 用表级<strong>意向锁</strong>先打标：</p><ul><li><strong>IS</strong>：打算给某些行加 S，先拿表 IS</li><li><strong>IX</strong>：打算给某些行加 X，先拿表 IX</li></ul><p>要锁整张表时，看表上有没有冲突的意向锁即可，不必遍历行。</p><h3 id="record、gap-与-next-key" tabindex="-1">Record、Gap 与 Next-Key <a class="header-anchor" href="#record、gap-与-next-key" aria-label="Permalink to &quot;Record、Gap 与 Next-Key&quot;">​</a></h3><p>三种行锁：</p><ul><li><strong>Record Lock</strong>：锁住已有索引记录</li><li><strong>Gap Lock</strong>：锁住记录之间的间隙，阻止别人往这个间隙插入</li><li><strong>Next-Key Lock</strong>：Record + 前面的 Gap，RR 当前读的默认形态</li></ul><p>插入意向锁让多个事务往<strong>不同</strong>间隙插入可以并行；往同一被 gap 锁住的间隙插入则等待。</p><p>RR 下：</p><ul><li>快照读靠 MVCC，不靠间隙锁</li><li>当前读靠 Next-Key 减少幻读</li><li>等值查询走唯一索引时，会优化成 Record Lock，不必锁间隙</li></ul><p>排查用 <code>SHOW ENGINE INNODB STATUS</code>、<code>performance_schema.data_locks</code>。等锁超时由 <code>innodb_lock_wait_timeout</code> 控制，默认 50 秒。</p><h3 id="乐观锁和悲观锁" tabindex="-1">乐观锁和悲观锁 <a class="header-anchor" href="#乐观锁和悲观锁" aria-label="Permalink to &quot;乐观锁和悲观锁&quot;">​</a></h3><p><strong>悲观锁</strong>假定会发生冲突：<code>SELECT ... FOR UPDATE</code>，或把隔离级别提到 SERIALIZABLE。冲突多、不能接受覆盖写时用。</p><p><strong>乐观锁</strong>先改，提交时再检测。常见是表上加 <code>version</code>：</p><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> product</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>影响行数为 0，说明被别人改过，业务重试。CAS 是同一思路。读多写少、冲突少时更合适。</p><h3 id="死锁-检测后回滚-不是把超时调大" tabindex="-1">死锁：检测后回滚，不是把超时调大 <a class="header-anchor" href="#死锁-检测后回滚-不是把超时调大" aria-label="Permalink to &quot;死锁：检测后回滚，不是把超时调大&quot;">​</a></h3><p>两个以上事务互相等对方持有的锁，就是死锁。InnoDB 用等待图检测，牺牲其中一个（通常 undo 更少的）回滚，错误号 1213。MyISAM 一次性拿齐表锁，几乎没有死锁。</p><p>减少死锁：</p><ul><li>多表、多行都按固定顺序访问</li><li>事务尽量短，不要在事务里做 RPC</li><li>要改就直接加 X 锁，不要先 S 再升级成 X</li><li>条件走索引，锁范围更准</li><li>能接受的话降低隔离级别，减少 gap lock</li><li>批量更新先在应用侧按主键排好序</li></ul><p>死锁发生后看最新死锁日志，调整 SQL 顺序。把 <code>innodb_lock_wait_timeout</code> 调大只是让会话等得更久，解决不了循环等待。</p>`,30)]))}const y=i(l,[["render",n]]);export{g as __pageData,y as default};
